1	using Microsoft.EntityFrameworkCore;
2	using seed_b_backend.Api.Data;
3	using seed_b_backend.Api.Data.Entities;
4	using seed_b_backend.Api.Dtos;
5	using seed_b_backend.Api.Services;
6	
7	namespace seed_b_backend.Tests.Services;
8	
9	public class OrderServiceTests
10	{
11	    private static AppDbContext CreateContext() =>
12	        new(new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options);
13	
14	    private static async Task SeedOfferAsync(AppDbContext db, string productId = "P1", string supplierId = "L1", decimal price = 10m)
15	    {
16	        if (!await db.Categories.AnyAsync(c => c.Id == "C1"))
17	        {
18	            db.Categories.Add(new Category { Id = "C1", Name = "Kategorie 1" });
19	        }
20	        if (!await db.Subcategories.AnyAsync(s => s.Id == "S1"))
21	        {
22	            db.Subcategories.Add(new Subcategory { Id = "S1", Name = "Unterkategorie 1", CategoryId = "C1" });
23	        }
24	        if (!await db.Suppliers.AnyAsync(s => s.Id == supplierId))
25	        {
26	            db.Suppliers.Add(new Supplier { Id = supplierId, Name = $"Lieferant {supplierId}" });
27	        }
28	        if (!await db.Products.AnyAsync(p => p.Id == productId))
29	        {
30	            db.Products.Add(new Product { Id = productId, Name = $"Produkt {productId}", Description = "d", SubcategoryId = "S1", Attributes = "{}" });
31	        }
32	        db.Offers.Add(new Offer { ProductId = productId, SupplierId = supplierId, Price = price });
33	        await db.SaveChangesAsync();
34	    }
35	
36	    [Fact]
37	    public async Task CreateOrderAsync_ValidCart_SnapshotsSupplierNameAndCurrentPriceAndClearsNoTrace()
38	    {
39	        var db = CreateContext();
40	        await SeedOfferAsync(db, "P1", "L1", 19.99m);
41	        var service = new OrderService(db);
42	        var request = new CreateOrderRequestDto("Jonas", "Hauptstr. 1", "12345", "Berlin", "DE", "j@example.com",
43	            [new OrderLineRequestDto("P1", "L1", 2)]);
44	
45	        var result = await service.CreateOrderAsync(request);
46	
47	        Assert.NotNull(result.OrderId);
48	        var order = await db.Orders.Include(o => o.Items).SingleAsync(o => o.Id == result.OrderId);
49	        Assert.Equal("Eingegangen", order.Status);
50	        var item = Assert.Single(order.Items);
51	        Assert.Equal("Lieferant L1", item.SupplierName);
52	        Assert.Equal(19.99m, item.UnitPrice);
53	        Assert.Equal(2, item.Quantity);
54	    }
55	
56	    [Fact]
57	    public async Task CreateOrderAsync_SupplierChangesPriceAfterOrder_OrderItemPriceStaysFrozen()
58	    {
59	        var db = CreateContext();
60	        await SeedOfferAsync(db, "P1", "L1", 19.99m);
61	        var service = new OrderService(db);
62	        var request = new CreateOrderRequestDto("Jonas", "Hauptstr. 1", "12345", "Berlin", "DE", "j@example.com",
63	            [new OrderLineRequestDto("P1", "L1", 1)]);
64	        var result = await service.CreateOrderAsync(request);
65	
66	        var offer = await db.Offers.SingleAsync(o => o.ProductId == "P1" && o.SupplierId == "L1");
67	        offer.Price = 29.99m;
68	        await db.SaveChangesAsync();
69	
70	        var item = await db.OrderItems.SingleAsync(i => i.OrderId == result.OrderId);
71	        Assert.Equal(19.99m, item.UnitPrice);
72	    }
73	
74	    [Fact]
75	    public async Task CreateOrderAsync_EmptyItemsList_RejectsWithEmptyCartAndPersistsNothing()
76	    {
77	        var db = CreateContext();
78	        var service = new OrderService(db);
79	        var request = new CreateOrderRequestDto("Jonas", "Hauptstr. 1", "12345", "Berlin", "DE", "j@example.com", []);
80	
81	        var result = await service.CreateOrderAsync(request);
82	
83	        Assert.Null(result.OrderId);
84	        Assert.Equal("empty-cart", result.RejectionReason);
85	        Assert.Equal(0, await db.Orders.CountAsync());
86	        Assert.Equal(0, await db.OrderItems.CountAsync());
87	    }
88	
89	    [Fact]
90	    public async Task CreateOrderAsync_NullItems_RejectsWithEmptyCartWithoutThrowing()
91	    {
92	        var db = CreateContext();
93	        var service = new OrderService(db);
94	        var request = new CreateOrderRequestDto("Jonas", "Hauptstr. 1", "12345", "Berlin", "DE", "j@example.com", null!);
95	
96	        var result = await service.CreateOrderAsync(request);
97	
98	        Assert.Equal("empty-cart", result.RejectionReason);
99	    }
100	
101	    [Fact]
102	    public async Task CreateOrderAsync_NullItemAmongValidItems_RejectsWithInvalidQuantityWithoutThrowing()
103	    {
104	        var db = CreateContext();
105	        await SeedOfferAsync(db, "P1", "L1", 10m);
106	        var service = new OrderService(db);
107	        var request = new CreateOrderRequestDto("Jonas", "Hauptstr. 1", "12345", "Berlin", "DE", "j@example.com",
108	            [new OrderLineRequestDto("P1", "L1", 1), null!]);
109	
110	        var result = await service.CreateOrderAsync(request);
111	
112	        Assert.Equal("invalid-quantity", result.RejectionReason);
113	        Assert.Equal(0, await db.Orders.CountAsync());
114	        Assert.Equal(0, await db.OrderItems.CountAsync());
115	    }
116	
117	    [Fact]
118	    public async Task CreateOrderAsync_OneInvalidQuantityAmongValidItems_RejectsWholeRequestAndPersistsNothing()
119	    {
120	        var db = CreateContext();
121	        await SeedOfferAsync(db, "P1", "L1", 10m);
122	        await SeedOfferAsync(db, "P2", "L1", 20m);
123	        var service = new OrderService(db);
124	        var request = new CreateOrderRequestDto("Jonas", "Hauptstr. 1", "12345", "Berlin", "DE", "j@example.com",
